    if(!_ks.length||typeof hudKey!=='function'){ ctx.fillText(_bcT,W/2,_y); return; }   // v13.52: no pad button reaches V; v18.71: the key as set
    ctx.save(); ctx.beginPath(); ctx.rect(_x0-_bcF,_y-_a-_bcF,_tw+_bcF*2,_a+_bcF*2);
