   function grab(){ rec=[]; PR.fillText=function(s,x,y){ rec.push({s:String(s),lo:String(s).toLowerCase(),a:this.globalAlpha}); return ot.apply(this,arguments); }; try{ __frame(0.016); } finally { PR.fillText=ot; } }
